import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';

/** Banner keys are generated by the api: a UUID and the format. Nothing else is ever stored. */
export const BANNER_KEY = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.webp$/;

/**
 * Where event banners live. Local disk in development and tests; S3 behind a CDN in AWS (to
 * come with the deploy pipeline). Callers never build image URLs themselves.
 */
export abstract class BannerStorage {
  abstract put(key: string, image: Buffer): Promise<void>;
  abstract remove(key: string): Promise<void>;
  abstract publicUrl(key: string): string;
  /** Only stores the api serves itself return the bytes; a CDN-backed store returns null. */
  abstract read(key: string): Promise<Buffer | null>;
}

export class LocalDiskBannerStorage extends BannerStorage {
  private readonly dir: string;

  constructor(
    dir: string,
    private readonly baseUrl: string,
  ) {
    super();
    this.dir = resolve(dir);
  }

  async put(key: string, image: Buffer): Promise<void> {
    await mkdir(this.dir, { recursive: true });
    await writeFile(this.path(key), image);
  }

  async remove(key: string): Promise<void> {
    await rm(this.path(key), { force: true });
  }

  publicUrl(key: string): string {
    return `${this.baseUrl}/${key}`;
  }

  async read(key: string): Promise<Buffer | null> {
    try {
      return await readFile(this.path(key));
    } catch {
      return null;
    }
  }

  private path(key: string): string {
    if (!BANNER_KEY.test(key)) throw new Error('Invalid banner key');
    return join(this.dir, key);
  }
}

export function bannerStorageFromEnv(env: NodeJS.ProcessEnv = process.env): BannerStorage {
  const transport = env.BANNER_STORAGE ?? 'local';
  if (transport !== 'local') {
    throw new Error(`BANNER_STORAGE=${transport} is not supported yet`);
  }
  const webUrl = env.WEB_URL ?? 'http://localhost:3000';
  return new LocalDiskBannerStorage(
    env.BANNER_DIR ?? 'var/banners',
    env.BANNER_PUBLIC_BASE_URL ?? `${webUrl}/api/public/banners`,
  );
}
